import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const textureMap = ctx.textureLoader.load(config.imageUrl);
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Calculate plane dimensions from atlas region (512x320)
  const aspectRatio = 512 / 320;
  const height = 1.0;
  const width = aspectRatio * height;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create material with TSL texture node
  const colorNode = texture(textureMap);
  const material = new MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create and add mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene position, rotation, and scale
  if (config.scenePosition) {
    const pos = config.scenePosition;
    group.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);
    if (pos.rotationXYZ) {
      group.rotation.set(
        pos.rotationXYZ[0] ?? 0,
        pos.rotationXYZ[1] ?? 0,
        pos.rotationXYZ[2] ?? 0
      );
    }
    if (pos.scaleXYZ) {
      group.scale.set(
        pos.scaleXYZ[0] ?? 1,
        pos.scaleXYZ[1] ?? 1,
        pos.scaleXYZ[2] ?? 1
      );
    }
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  // Event handlers
  group.userData.handlers = {};

  return group;
}
